  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  // Step 1: Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) return false;

  // Step 2: Drop the Product table if it exists
  if (!(*conn)->execute("DROP TABLE IF EXISTS Product")) return false;

  // Step 3: Create the Product table
  auto result = sqlgen::create_table_impl<Product>(*conn, false);
  if (!result) return false;

  // Step 4: Begin a transaction
  auto trans = sqlgen::begin_transaction(result);
  if (!trans) return false;

  // Step 5: Insert all products in the transaction
  auto insert_res = sqlgen::insert(trans, products);
  if (!insert_res) return false;

  // Step 6: Commit the transaction
  auto commit_res = sqlgen::commit(insert_res);

  return commit_res.has_value();
}

}  // namespace batch_insert_products

