  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  using namespace sqlgen;

  // Connect to database, create tables, and execute query
  auto result = 
    sqlite::connect("test_db.sqlite")
    | create_table<Course>{.if_not_exists_ = true}
    | create_table<Enrollment>{.if_not_exists_ = true}
    | select_from<Course, "c">(
        col<"c", "title">,
        count(col<"e", "enrollment_id">),
        avg(col<"e", "grade">)
      )
    | left_join<Enrollment, "e">(
        col<"c", "course_id"> == col<"e", "course_id">
      )
    | group_by(
        col<"c", "course_id">,
        col<"c", "title">
      )
    | to<std::vector<CourseStats>>;

  // Return results or empty vector on error
  if (result) {
    return *result;
  }

  return {};
}

}  // namespace query_course_enrollment_stats
