#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_employee_hierarchy {

struct Employee {
  sqlgen::PrimaryKey<int> emp_id;
  std::string name;
  std::optional<int> manager_id;
};

struct EmployeeManager {
  std::string employee;
  std::optional<std::string> manager;
};

std::vector<EmployeeManager> query_employee_hierarchy() {
    using namespace sqlgen;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Build and execute the query with self-join
    // SELECT e1.name as employee, e2.name as manager
    // FROM Employee e1
    // LEFT JOIN Employee e2 ON e1.manager_id = e2.emp_id
    auto query = select_from<Employee, "e1">(
        col<"e1", "name"> | as<"employee">,
        col<"e2", "name"> | as<"manager">
    )
    | left_join<Employee, "e2">(
        col<"e1", "manager_id"> == col<"e2", "emp_id">
    )
    | to<std::vector<EmployeeManager>>;

    return query(conn).value();
}

}  // namespace query_employee_hierarchy
```

**Explanation:**

1. **Connection**: Uses `sqlgen::sqlite::connect("test_db.sqlite")` to connect to the SQLite database file.

2. **Self-Join Query**: 
   - `select_from<Employee, "e1">(...)` - Selects from the Employee table with alias "e1"
   - Selects two columns: `e1.name` aliased as "employee" and `e2.name` aliased as "manager"
   - Uses the pipe operator `|` with `as<"name">` to alias columns to match the `EmployeeManager` struct fields

3. **LEFT JOIN**: 
   - `left_join<Employee, "e2">(...)` - Joins the Employee table again with alias "e2"
   - The join condition `col<"e1", "manager_id"> == col<"e2", "emp_id">` matches employees to their managers
   - LEFT JOIN ensures employees without managers (NULL manager_id) are still included

4. **Result Mapping**: 
   - `to<std::vector<EmployeeManager>>` specifies the return container type
   - The `manager` field in `EmployeeManager` is `std::optional<std::string>` to handle NULL values for top-level employees

5. **Execution**: Calls the query with the connection and extracts the value using `.value()`

