#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_product_sales_report {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string category;
};

struct Sale {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct CategoryReport {
  std::string category;
  int total_qty;
  double total_amt;
};

struct ProductSalesReport {
  static constexpr const char* tablename = "ProductSalesReport";
  static constexpr bool is_view = true;
  std::string category;
  int total_qty;
  double total_amt;
};

std::vector<CategoryReport> query_product_sales_report() {
    using namespace sqlgen;

    // Connect to SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Build the query:
    // SELECT p.category, SUM(s.quantity) as total_qty, SUM(s.amount) as total_amt
    // FROM Product p
    // INNER JOIN Sale s ON p.product_id = s.product_id
    // GROUP BY p.category
    auto query = select_from<Product, "p">(
        col<"p", "category">,
        sum(col<"s", "quantity">) | as<"total_qty">,
        sum(col<"s", "amount">) | as<"total_amt">
    )
    | inner_join<Sale, "s">(col<"p", "product_id"> == col<"s", "product_id">)
    | group_by(col<"p", "category">)
    | to<std::vector<CategoryReport>>;

    // Execute query and get all results
    auto all_results = query(conn).value();

    // Filter results with total_amt > 5000 (HAVING clause equivalent)
    std::vector<CategoryReport> results;
    for (const auto& report : all_results) {
        if (report.total_amt > 5000.0) {
            results.push_back(report);
        }
    }

    return results;
}

}  // namespace query_product_sales_report
