    };

    using IteratorType = internal::iterator_t<
        transpilation::fields_to_named_tuple_t<TableTupleType, FieldsType>,
        decltype(_conn)>;

    using RangeType = Range<IteratorType>;

    return select_from_impl<TableTupleType, AliasType, FieldsType,
