                                                typename ColTypes::ColType...>,
                      OrderByType, LimitType, ToType>{.fields_ = _s.fields_,
                                                      .from_ = _s.from_,
                                                      .joins_ = _s.joins_,
                                                      .where_ = _s.where_};
  }

  template <class... ColTypes>
