struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  using namespace sqlgen;

  // Step 1: Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Step 2: Drop the view if it exists (SQLite compatibility - manual handling)
  auto conn_after_drop = conn | (drop<SalesSummary> | if_exists);
  if (!conn_after_drop) {
    return false;
  }

  // Step 3: Build the SELECT query for the view
  // SELECT p.name as product_name, SUM(s.quantity) as total_quantity, SUM(s.amount) as total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name
  auto select_query = select_from<Sale, "s">(
    col<"p", &Product::name>,
    sum(col<"s", &Sale::quantity>),
    sum(col<"s", &Sale::amount>)
  )
  | join<Product, "p">(col<"s", &Sale::product_id> == col<"p", &Product::product_id>)
  | group_by(col<"p", &Product::name>);

  // Step 4: Create the view using create_as
  auto result = conn_after_drop | create_as<SalesSummary>(select_query);

  // Step 5: Return success status
  return result.has_value();
}

}  // namespace schema_create_view_sales_summary
