 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query with RIGHT JOIN
  // This performs: SELECT d.name as department_name, p.name as project_name
  //                FROM Department d RIGHT JOIN Project p 
  //                ON d.department_id = p.department_id
  // This includes all projects, with optional department information
  auto query = sqlgen::select_from<Department, "d">(
      sqlgen::col<"d", "name"> | sqlgen::as<"department_name">,
      sqlgen::col<"p", "name"> | sqlgen::as<"project_name">
  )
  | sqlgen::right_join<Project, "p">(
      sqlgen::col<"d", "department_id"> == sqlgen::col<"p", "department_id">
  )
  | sqlgen::to<std::vector<DepProj>>;

  // Execute the query
  auto result = query(conn);

  // Return the result or empty vector on error
  if (result) {
    return std::move(*result);
  }
  return {};
}

}  // namespace right_join_departments_projects
