/**
 * This function demonstrates how to build a conditional SQL query.
 * It joins tables A and B, filtering for records where score > 10 and name contains 'x'.
 * Returns: std::string.
 */
std::string generate_sql_dry_run() {
  using namespace sqlgen;

  // Build complex query with joins, where clause, order_by, and limit
  // SELECT a.id, a.name, b.score FROM A as a
  // INNER JOIN B as b ON a.id = b.a_id
  // WHERE b.score > 10.0 AND a.name LIKE '%x%'
  // ORDER BY b.score
  // LIMIT 100
  auto query = select_from<A, "a">(
      col<"a", &A::id>,
      col<"a", &A::name>,
      col<"b", &B::score>
    )
    | inner_join<B, "b">(col<"a", &A::id> == col<"b", &B::a_id>)
    | where((col<"b", &B::score> > 10.0) && (col<"a", &A::name>.like("%x%")))
    | order_by(col<"b", &B::score>)
    | limit(100);

  // Generate SQL string without execution (dry run for debugging)
  std::string sql = sqlite::to_sql(query);

  return sql;
