    const std::vector<Friendship>& friendships) {

  using namespace sqlgen;

  // Step 1: Connect to SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return {};
  }

  // Step 2: Create tables for User and Friendship
  auto table_result = *conn_result
    | create_table<User>{}
    | create_table<Friendship>{};

  if (!table_result) {
    return {};
  }

  auto conn = *table_result;

  // Step 3: Insert user data
  for (const auto& user : users) {
    auto insert_result = conn->insert(user);
    if (!insert_result) {
      return {};
