    if (!insert_result) {
      return {};
    }
  }

  // Step 4: Insert friendship data
  for (const auto& friendship : friendships) {
    auto insert_result = conn->insert(friendship);
    if (!insert_result) {
      return {};
    }
  }

  // Step 5: Query for friend connections using SELF-JOIN
  // This query finds all friendships and retrieves the usernames
  // SELECT u1.username as user1_name, u2.username as user2_name
  // FROM Friendship f
  // INNER JOIN User u1 ON f.user1_id = u1.user_id
  // INNER JOIN User u2 ON f.user2_id = u2.user_id
  auto query_result = conn
    | select_from<Friendship, "f">(
        col<"u1", "username"> | as<"user1_name">,
        col<"u2", "username"> | as<"user2_name">
      )
    | inner_join<User, "u1">(
        col<"f", "user1_id"> == col<"u1", "user_id">
      )
    | inner_join<User, "u2">(
        col<"f", "user2_id"> == col<"u2", "user_id">
      )
    | to<std::vector<FriendConnection>>;

  if (!query_result) {
    return {};
  }

  return *query_result;
}

}  // namespace analyze_social_network

