  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return {};
  }
  auto conn = *conn_result;

  // Create OrderItem table
  auto create_result = conn->execute(R"(
    DROP TABLE IF EXISTS OrderItem;
    CREATE TABLE OrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    );
  )");

  if (!create_result) {
    return {};
  }

  // Insert items into the table
  for (const auto& item : items) {
    std::ostringstream sql;
    sql << "INSERT INTO OrderItem (item_id, order_id, product_id, unit_price, quantity, discount_rate, tax_rate) VALUES ("
        << item.item_id.value << ", "
        << item.order_id << ", "
        << item.product_id << ", "
        << item.unit_price << ", "
        << item.quantity << ", "
        << (item.discount_rate.has_value() ? std::to_string(*item.discount_rate) : "NULL") << ", "
        << (item.tax_rate.has_value() ? std::to_string(*item.tax_rate) : "NULL") << ")";

    auto insert_result = conn->execute(sql.str());
    if (!insert_result) {
      return {};
    }
  }

  // Execute query with arithmetic operations to calculate business metrics
  std::string query = R"(
    SELECT 
      item_id,
      order_id,
      product_id,
      unit_price,
      quantity,
      COALESCE(discount_rate, 0.0) as discount_rate,
      COALESCE(tax_rate, 0.0) as tax_rate,
      (unit_price * quantity) as gross_total,
      (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100)) as discounted_total,
      (unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100) * (1 + COALESCE(tax_rate, 0)/100)) as final_total,
      (unit_price * quantity / quantity) as unit_cost,
      (quantity % 10) as quantity_group,
      (unit_price * 0.3) as estimated_profit
    FROM OrderItem
  )";

  auto result = conn->template read<std::vector<OrderMetrics>>(query);

  return result.value_or(std::vector<OrderMetrics>{});
}

}  // namespace calculate_order_metrics

