  requires is_connection<Connection>
Result<Ref<Connection>> write(const Result<Ref<Connection>>& _res,
                              ItBegin _begin, ItEnd _end) noexcept {
  return _res.and_then(
      [&](const auto& _conn) { return write(_conn, _begin, _end); });
}

