    // Create the complex condition: age < 18 OR status = 'inactive'
    auto condition = "age"_c < 18 || "status"_c == "inactive";

    // Build the delete statement with the where clause
    auto delete_query = sqlgen::delete_from<User> | sqlgen::where(condition);

    // Convert to SQL string using SQLite dialect
    return sqlgen::sqlite::to_sql(delete_query);
