# Complete Implementation

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // Connect to the SQLite database
  sqlgen::sqlite::Database db("test_db.sqlite");

  // Create table references with aliases
  auto p = sqlgen::table<Product>("Product").as("p");
  auto s = sqlgen::table<Sales>("Sales").as("s");

  // Build the query with JOIN, aggregation, grouping, ordering, and limit
  auto total_sales = sqlgen::sum(p["price"] * s["quantity"]);

  auto query = sqlgen::select(
      p["product_id"],
      p["product_name"],
      p["category"],
      total_sales.as("total_sales")
    )
    .from(p)
    .inner_join(s).on(p["product_id"] == s["product_id"])
    .group_by(p["product_id"], p["product_name"], p["category"])
    .order_by(total_sales, sqlgen::Order::DESC)
    .limit(limit_count);

  // Execute the query
  auto result_set = db.execute(query);

  // Map results to TopProduct vector
  std::vector<TopProduct> results;
  for (const auto& row : result_set) {
    TopProduct tp;
    tp.product_id = row.get<int>("product_id");
    tp.product_name = row.get<std::string>("product_name");
    tp.category = row.get<std::string>("category");
    tp.total_sales = row.get<double>("total_sales");
    results.push_back(tp);
  }

  return results;
}

}  // namespace get_top_products
